from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download'
css=(r/'docs/replica/source/original.css').read_text()
import re
hover=re.findall(r'tbody tr:hover\{([^}]+)\}',css)[-1]
(o/'capabilityrow-motion.html').write_text('''<!doctype html><meta charset="utf-8"><title>CapabilityRow motion · original isolation</title><link rel="stylesheet" href="capabilityrow-original.css"><style>body{padding:30px}tbody tr.fixture-hover{'''+hover+'''}</style><button id="capabilityrow-motion-record">Record capability row motion</button><div id="fixtures"></div><script>
document.getElementById('capabilityrow-motion-record').onclick=async()=>{const rows=[];for(const scenario of ['hover','unhover','hover-reverse','unhover-reverse']){const table=document.createElement('table');table.className='capability-table';table.innerHTML='<tbody><tr><td>Original row transition</td></tr></tbody>';document.getElementById('fixtures').append(table);const el=table.querySelector('tr');el.style.transition='none';el.classList.toggle('fixture-hover',scenario.startsWith('unhover'));getComputedStyle(el).backgroundColor;el.style.transition='';getComputedStyle(el).backgroundColor;el.classList.toggle('fixture-hover',scenario.startsWith('hover'));getComputedStyle(el).backgroundColor;let animations=el.getAnimations();if(animations.length!==1)throw Error('Original row transition missing');for(const a of animations){a.pause();a.currentTime=0}let reverseDuration=null;if(scenario.endsWith('reverse')){for(const a of animations)a.currentTime=30;getComputedStyle(el).backgroundColor;el.classList.toggle('fixture-hover',scenario.startsWith('unhover'));getComputedStyle(el).backgroundColor;animations=el.getAnimations();for(const a of animations){a.pause();a.currentTime=0}reverseDuration=animations[0]?.effect.getTiming().duration??null}
for(const ms of [0,.5,8,16,30,40,60,80,120,160,200,240]){for(const a of animations)a.currentTime=ms;rows.push({scenario,ms,value:getComputedStyle(el).backgroundColor,reverseDuration})}table.remove();}const result=await fetch('/evidence/preflight-capabilityrow-'+(new URLSearchParams(location.search).get('os')==='mac'?'mac':'windows')+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows})});if(!result.ok)throw Error('Motion record failed');document.getElementById('capabilityrow-motion-record').textContent='Capability row motion recorded';};</script>''')
print('Original capability row CSS timing fixture prepared')
